/**
 * @method
 * @name dts_All_HD_LIST_OnLoadCompleted
 * @description dts_All_HD_LIST 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_All_HD_LIST_OnLoadCompleted = function(rowcount) {
    try {
        $c.stf.fillGridHeaderTotalCnt(rowcount, panel_page_1);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF35500.dts_All_HD_LIST_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name grd_All_HD_LIST_OnDblClick
 * @description grd_All_HD_LIST 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_All_HD_LIST_OnDblClick = async function(row, colid) {
    try {
        if (colid === "ISU_KOR_ABBRV") {
            await scwin.openDetail(row);
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF35500.grd_All_HD_LIST_OnDblClick" });
    }
};

