///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name setElwInstNm1
 * @description set Elw Inst Nm1 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setElwInstNm1 = async function() {
    const sbmOptions = {
        id : "sbm_dts_ELW_INST_NM_1",
        action : "/CodeAction.do",
        ref : "",
        target : "dts_ELW_INST_NM_1=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name listSync
 * @description list Sync 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.listSync = async function() {
    if (MaxTab_01.getSelectedTabIndex() === 1) {
        /*var gLog = getObjectValue(chk_Log);
        if (gLog == 'Y') {
        	gLog  = 'N';
        } else {
        	gLog  = 'Y';
        }*/
        const gLog = 'N';
        url += "&LIST_DD=" + edt_TASK_DD.getValue();
        url += "&ISU_CD=" + cmb_ELW_INST_NM_1.getValue();
        url += "&DELIST_DTEC_YN=" + gLog;
        const sbmOptions = {
            id : "sbm_dts_All_HD_LIST",
            action : "/ELWAllHoldAction.do",
            ref : "",
            target : "dts_All_HD_LIST=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    }
};

/**
         * @method
         * @name setTaskDd
         * @description set Task Dd 처리
         * @returns {Promise<void>}
         * @hidden N
         */
scwin.setTaskDd = async function() {
    const sbmOptions = {
        id : "sbm_dts_TASK_DD",
        action : "/ELWAllHoldAction.do",
        ref : "",
        target : "dts_TASK_DD=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name openDetail
 * @description open Detail 처리
 * @param {Number} row 행 인덱스
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.openDetail = async function(row) {
    if (row > 0) {
        // 그리드에서 선택시
        scwin.clickIsuCd = dts_All_HD_LIST.getCellData(row, "ISU_CD");
        scwin.clickIsuKorAbbrv = dts_All_HD_LIST.getCellData(row, "ISU_KOR_ABBRV");
        const options = {
            id: "ULDSTF35503",
            title: "개별종목보유수량조회",
            type: "pageFramePopup",
            width: "905px",
            height: 570 + 35
        };

        const data = {
            // TO-DO : 팝업으로 전달할 파라미터 설정
        };

        const result = await $c.win.openPopup("/lstmgt/ULDSTF35503.gfm", options, data);
        // TO-DO : result 값 확인 후 업무 로직 추가
    }
};

/**
 * @method
 * @name excelDown
 * @description excel Down 처리
 * @returns {void}
 * @hidden N
 */
scwin.excelDown = function() {
    if (MaxTab_01.getSelectedTabIndex() === 1) {
        // 엑셀 로그
        $c.stf.doLogSave("ULDSTF35500.xml", SCREN_PROCS_TP_CD_07);
        $c.data.downloadGridViewExcel(grd_All_HD_LIST, {fileName: "전부보유리스트", type: "8"});
    }
};
